use rukki::pseudo_hap;
use rukki::Graph;
use std::fs;
use std::process::Command;

#[test]
fn pseudo_hap_exposes_complementary_seed_sets() {
    let graph = Graph::read(
        &"S s * LN:i:100\n\
          S a * LN:i:100\n\
          S b * LN:i:100\n\
          S t * LN:i:100\n\
          L s + a + 0M\n\
          L a + t + 0M\n\
          L s + b + 0M\n\
          L b + t + 0M\n"
            .replace(' ', "\t"),
    );
    let blocks = pseudo_hap::pseudo_hap_decompose(&graph, 1);
    let bubble = blocks
        .iter()
        .find(|block| !block.known_alt_nodes().is_empty())
        .expect("simple bubble was not decomposed");

    assert!(bubble.shared_nodes().contains(&graph.name2id("s")));
    assert!(bubble.shared_nodes().contains(&graph.name2id("t")));
    assert_eq!(bubble.known_alt_nodes().len(), 1);
    assert_eq!(bubble.primary_exclusive_nodes().count(), 1);
}

#[test]
fn dual_estimates_coverage_and_handles_haploid_components() {
    let test_dir = std::env::temp_dir().join(format!("rukki-dual-{}", std::process::id()));
    let _ = fs::remove_dir_all(&test_dir);
    fs::create_dir_all(&test_dir).unwrap();
    let graph = test_dir.join("graph.gfa");
    let colors = test_dir.join("colors.tsv");
    fs::write(
        &graph,
        "S\ts\t*\tLN:i:100\tll:f:40\n\
         S\ta\t*\tLN:i:100\tll:f:20\n\
         S\tb\t*\tLN:i:100\tll:f:20\n\
         S\tt\t*\tLN:i:100\tll:f:40\n\
         S\thaploid\t*\tLN:i:100\tll:f:20\n\
         S\tcollapsed\t*\tLN:i:100\tll:f:40\n\
         L\ts\t+\ta\t+\t0M\n\
         L\ta\t+\tt\t+\t0M\n\
         L\ts\t+\tb\t+\t0M\n\
         L\tb\t+\tt\t+\t0M\n",
    )
    .unwrap();

    let result = Command::new(env!("CARGO_BIN_EXE_rukki"))
        .args([
            "dual",
            "--graph",
            graph.to_str().unwrap(),
            "--colors",
            colors.to_str().unwrap(),
            "--unique-block-len",
            "1",
        ])
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );

    let rows = fs::read_to_string(&colors).unwrap();
    let haploid = rows
        .lines()
        .find(|line| line.starts_with("haploid\t"))
        .expect("haploid component missing from colors");
    let collapsed = rows
        .lines()
        .find(|line| line.starts_with("collapsed\t"))
        .expect("collapsed component missing from colors");
    assert!(!haploid.contains("\tHOM\t"));
    assert!(collapsed.contains("\tHOM\t"));

    fs::remove_dir_all(test_dir).unwrap();
}

#[test]
fn haploid_flag_changes_graph_wide_coverage_fallback() {
    let test_dir = std::env::temp_dir().join(format!("rukki-dual-haploid-{}", std::process::id()));
    let _ = fs::remove_dir_all(&test_dir);
    fs::create_dir_all(&test_dir).unwrap();
    let graph = test_dir.join("graph.gfa");
    let diploid_colors = test_dir.join("diploid.tsv");
    let haploid_colors = test_dir.join("haploid.tsv");
    fs::write(
        &graph,
        "S\tone\t*\tLN:i:100\tll:f:20\n\
         S\ttwo\t*\tLN:i:100\tll:f:20\n",
    )
    .unwrap();

    for (output, haploid) in [(&diploid_colors, false), (&haploid_colors, true)] {
        let mut command = Command::new(env!("CARGO_BIN_EXE_rukki"));
        command.args([
            "dual",
            "--graph",
            graph.to_str().unwrap(),
            "--colors",
            output.to_str().unwrap(),
            "--unique-block-len",
            "1",
        ]);
        if haploid {
            command.arg("--haploid");
        }
        let result = command.output().unwrap();
        assert!(
            result.status.success(),
            "{}",
            String::from_utf8_lossy(&result.stderr)
        );
    }

    let diploid = fs::read_to_string(diploid_colors).unwrap();
    let haploid = fs::read_to_string(haploid_colors).unwrap();
    assert_eq!(diploid.matches("\tHOM\t").count(), 2);
    assert_eq!(haploid.matches("\tHOM\t").count(), 0);
    assert!(haploid.contains("\tHAPLOTYPE1\t") || haploid.contains("\tHAPLOTYPE2\t"));

    fs::remove_dir_all(test_dir).unwrap();
}

#[test]
fn dual_splits_bowtie_arms_around_collapsed_anchor() {
    let test_dir = std::env::temp_dir().join(format!("rukki-dual-bowtie-{}", std::process::id()));
    let _ = fs::remove_dir_all(&test_dir);
    fs::create_dir_all(&test_dir).unwrap();
    let graph = test_dir.join("graph.gfa");
    let colors = test_dir.join("colors.tsv");

    // The ordinary bubble supplies an unambiguous haploid-depth estimate.
    // The disconnected bowtie models a short collapsed node joining four
    // chromosome-scale haploid arms, as seen in the chr9/12/17 examples.
    fs::write(
        &graph,
        "S\ts\t*\tLN:i:100\tll:f:40\n\
         S\ta\t*\tLN:i:600\tll:f:20\n\
         S\tb\t*\tLN:i:600\tll:f:20\n\
         S\tt\t*\tLN:i:100\tll:f:40\n\
         S\tleft1\t*\tLN:i:1000\tll:f:20\n\
         S\tleft2\t*\tLN:i:900\tll:f:20\n\
         S\tcenter\t*\tLN:i:100\tll:f:40\n\
         S\tright1\t*\tLN:i:1100\tll:f:20\n\
         S\tright2\t*\tLN:i:800\tll:f:20\n\
         L\ts\t+\ta\t+\t0M\n\
         L\ta\t+\tt\t+\t0M\n\
         L\ts\t+\tb\t+\t0M\n\
         L\tb\t+\tt\t+\t0M\n\
         L\tleft1\t+\tcenter\t+\t0M\n\
         L\tleft2\t+\tcenter\t+\t0M\n\
         L\tcenter\t+\tright1\t+\t0M\n\
         L\tcenter\t+\tright2\t+\t0M\n",
    )
    .unwrap();

    let result = Command::new(env!("CARGO_BIN_EXE_rukki"))
        .args([
            "dual",
            "--graph",
            graph.to_str().unwrap(),
            "--colors",
            colors.to_str().unwrap(),
            "--unique-block-len",
            "500",
            "--seed",
            "7",
        ])
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );

    let rows = fs::read_to_string(colors).unwrap();
    let assignment = |name: &str| {
        rows.lines()
            .find(|line| line.starts_with(&format!("{name}\t")))
            .unwrap()
            .split('\t')
            .nth(1)
            .unwrap()
            .to_owned()
    };
    assert_eq!(assignment("s"), "HOM");
    assert_eq!(assignment("t"), "HOM");
    assert_ne!(assignment("a"), assignment("b"));
    assert_eq!(assignment("center"), "HOM");
    assert_ne!(assignment("left1"), assignment("left2"));
    assert_ne!(assignment("right1"), assignment("right2"));

    fs::remove_dir_all(test_dir).unwrap();
}

#[test]
fn dual_pairs_similar_linear_blocks_across_an_unresolved_core() {
    let test_dir =
        std::env::temp_dir().join(format!("rukki-dual-linear-pair-{}", std::process::id()));
    let _ = fs::remove_dir_all(&test_dir);
    fs::create_dir_all(&test_dir).unwrap();
    let graph = test_dir.join("graph.gfa");
    let colors = test_dir.join("colors.tsv");

    // The ordinary bubble supplies the coverage estimate.  The two long,
    // similarly sized arms are separate pseudo-hap blocks connected only by
    // a short zero-coverage unresolved core, as in acrocentric/rDNA regions.
    fs::write(
        &graph,
        "S\ts\t*\tLN:i:100\tll:f:40\n\
         S\ta\t*\tLN:i:600\tll:f:20\n\
         S\tb\t*\tLN:i:600\tll:f:20\n\
         S\tt\t*\tLN:i:100\tll:f:40\n\
         S\tarm1\t*\tLN:i:1200\tll:f:20\n\
         S\tarm2\t*\tLN:i:1100\tll:f:20\n\
         S\tcore\t*\tLN:i:100\tll:f:0\n\
         L\ts\t+\ta\t+\t0M\n\
         L\ta\t+\tt\t+\t0M\n\
         L\ts\t+\tb\t+\t0M\n\
         L\tb\t+\tt\t+\t0M\n\
         L\tarm1\t+\tcore\t+\t0M\n\
         L\tarm2\t+\tcore\t+\t0M\n",
    )
    .unwrap();

    let result = Command::new(env!("CARGO_BIN_EXE_rukki"))
        .args([
            "dual",
            "--graph",
            graph.to_str().unwrap(),
            "--colors",
            colors.to_str().unwrap(),
            "--unique-block-len",
            "500",
            "--seed",
            "11",
        ])
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );

    let rows = fs::read_to_string(&colors).unwrap();
    let assignment = |name: &str| {
        rows.lines()
            .find(|line| line.starts_with(&format!("{name}\t")))
            .unwrap()
            .split('\t')
            .nth(1)
            .unwrap()
            .to_owned()
    };
    assert_ne!(assignment("arm1"), assignment("arm2"));

    fs::remove_dir_all(test_dir).unwrap();
}

#[test]
fn dual_uses_homology_and_puts_the_shorter_member_in_haplotype1() {
    let test_dir = std::env::temp_dir().join(format!("rukki-dual-homology-{}", std::process::id()));
    let _ = fs::remove_dir_all(&test_dir);
    fs::create_dir_all(&test_dir).unwrap();
    let graph = test_dir.join("graph.gfa");
    let homology = test_dir.join("homology.tsv");
    let colors = test_dir.join("colors.tsv");

    fs::write(
        &graph,
        "S\ts\t*\tLN:i:100\tll:f:40\n\
         S\ta\t*\tLN:i:600\tll:f:20\n\
         S\tb\t*\tLN:i:600\tll:f:20\n\
         S\tt\t*\tLN:i:100\tll:f:40\n\
         S\tlonger\t*\tLN:i:1400\tll:f:20\n\
         S\tshorter\t*\tLN:i:900\tll:f:20\n\
         L\ts\t+\ta\t+\t0M\n\
         L\ta\t+\tt\t+\t0M\n\
         L\ts\t+\tb\t+\t0M\n\
         L\tb\t+\tt\t+\t0M\n",
    )
    .unwrap();
    fs::write(
        &homology,
        "node1\tnode2\thomology_length\nlonger\tshorter\t700\n",
    )
    .unwrap();

    let result = Command::new(env!("CARGO_BIN_EXE_rukki"))
        .args([
            "dual",
            "--graph",
            graph.to_str().unwrap(),
            "--homology",
            homology.to_str().unwrap(),
            "--colors",
            colors.to_str().unwrap(),
            "--unique-block-len",
            "500",
        ])
        .output()
        .unwrap();
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );

    let rows = fs::read_to_string(&colors).unwrap();
    let shorter = rows
        .lines()
        .find(|line| line.starts_with("shorter\t"))
        .unwrap();
    let longer = rows
        .lines()
        .find(|line| line.starts_with("longer\t"))
        .unwrap();
    assert!(shorter.contains("\tHAPLOTYPE1\t"));
    assert!(longer.contains("\tHAPLOTYPE2\t"));
    assert!(shorter.contains("\tdual-homology-block\t"));

    fs::remove_dir_all(test_dir).unwrap();
}
